    margin: 0;
    font-size: 1.1rem;
    color: #2d7d2d;
    font-weight: 700;
}

.product-rating {
    color: #f5a623;
    font-size: 1.1rem;
}

.out-of-stock-badge {
    display: inline-block;
    background: #fee2e2;
    color: #dc2626;
