    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.add-to-cart-btn:hover:not(:disabled) {
    background: #1d4ed8;
}

.add-to-cart-btn:disabled {
    background: #d1d5db;
    color: #6b7280;
    cursor: not-allowed;
}

