.catalog-filters {
    padding: 1.5rem;
    background: #f9fafb;
    border-right: 1px solid #e5e7eb;
    height: 100%;
}

.catalog-filters h2 {
    margin: 0 0 1.5rem 0;
    font-size: 1.25rem;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    margin: 0 0 0.75rem 0;
    font-size: 0.9rem;
    font-weight: 600;
    text-transform: uppercase;
    color: #6b7280;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.price-inputs input {
    width: 80px;
    padding: 0.4rem 0.5rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    font-size: 0.9rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.6rem 1rem;
    background: #2563eb;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
}

.btn-apply:hover {
    background: #1d4ed8;
}

.btn-clear {
    padding: 0.6rem 1rem;
    background: transparent;
    color: #6b7280;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-weight: 500;
    cursor: pointer;
}

.btn-clear:hover {
    background: #f3f4f6;
}

