}

.sort-control select {
    padding: 0.4rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9rem;
    background: #fff;
}

.results-label {
    color: #6b7280;
    font-size: 0.9rem;
}

