toolArgs.file_text:
.catalog-page {
    display: grid;
    grid-template-columns: 25% 1fr;
    min-height: calc(100vh - 4rem);
}

.catalog-main {
    padding: 1.5rem 2rem;
}

.catalog-status {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem;
    text-align: center;
    color: #6b7280;
}

.catalog-status.error {
    color: #dc2626;
}

.catalog-status button {
    margin-top: 1rem;
    padding: 0.6rem 1.2rem;
    background: #2563eb;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
}

.catalog-status button:hover {
    background: #1d4ed8;
}

